/**
 * Codex instructions resolution (design:
 * docs/sub2api-parity-upgrade-plan-2026-10-15.md Phase 1.4/1.5, P0-2). The
 * ChatGPT codex backend rejects a request whose `instructions` field is empty,
 * so the gateway injects the real per-model-family Codex CLI base prompt
 * whenever the compiled outbound body carries none.
 *
 * The family texts and the minimal last-resort fallback live in
 * `instructions-families.generated.ts`, which is GENERATED by
 * `scripts/saas/codex-sync-instructions.ts` from the openai/codex release
 * artifacts (see `instructions/README.md`). Do not hand-edit prompt text.
 */
import { CODEX_FAMILY_INSTRUCTIONS, CODEX_INSTRUCTIONS_FALLBACK } from './instructions-families.generated.js';

export const CODEX_FALLBACK_INSTRUCTIONS_VERSION = 'codex-instructions-fallback/v1';

/**
 * Final non-empty guarantee: the minimal generic instruction from
 * `instructions/fallback.txt`, mirrored by the generated module so there is
 * exactly one source of truth for its bytes.
 */
export const CODEX_FALLBACK_INSTRUCTIONS = CODEX_INSTRUCTIONS_FALLBACK;

/** Families checked in prefix order; the last entry doubles as "latest". */
const MODEL_FAMILY_PREFIXES: readonly (readonly [prefix: string, family: string])[] = [
  ['gpt-5.6', 'gpt-5.6'],
  ['gpt-5.5', 'gpt-5.5'],
  ['gpt-5.4', 'gpt-5.4'],
  ['gpt-5.2', 'gpt-5.2'],
];

/** sub2api semantics: unknown models resolve to the latest-known family. */
const LATEST_FAMILY = 'gpt-5.5';

/**
 * Maps a model id to its Codex instruction family: lowercase/trim, strip any
 * provider prefix (segment after the last `/`), `codex` substring → the
 * GPT-5-Codex family, then gpt-5.x prefix matching, everything else (gpt-6*,
 * 5.3-era, unknown) → the latest-known family. Mirrors sub2api's
 * `CodexBaseInstructionsForModel`.
 */
export function codexModelFamily(model: string): string {
  const normalized = model.trim().toLowerCase();
  const bare = normalized.slice(normalized.lastIndexOf('/') + 1);
  if (bare.includes('codex')) return 'codex';
  for (const [prefix, family] of MODEL_FAMILY_PREFIXES) {
    if (bare.startsWith(prefix)) return family;
  }
  return LATEST_FAMILY;
}

/**
 * Resolves the family base instructions for one model. Never returns an empty
 * string: the requested family falls back to the latest family, then to the
 * minimal fallback constant, then to an inline non-empty literal.
 */
export function codexInstructionsForModel(model: string): string {
  const family = codexModelFamily(model);
  const chain = [
    CODEX_FAMILY_INSTRUCTIONS[family],
    CODEX_FAMILY_INSTRUCTIONS[LATEST_FAMILY],
    CODEX_INSTRUCTIONS_FALLBACK,
  ];
  for (const candidate of chain) {
    if (typeof candidate === 'string' && candidate.length > 0) return candidate;
  }
  return 'You are Codex, a coding assistant. Answer concisely and prefer runnable code.';
}

/**
 * Resolves the outbound instructions for one request: client-provided
 * instructions always win verbatim; otherwise the model's family base prompt
 * is injected so the upstream never sees an empty field. `model` is optional
 * for backward compatibility — without it the latest-known family is used.
 */
export function resolveCodexInstructions(clientInstructions: unknown, model?: string): string {
  if (typeof clientInstructions === 'string' && clientInstructions.trim().length > 0) {
    return clientInstructions;
  }
  return codexInstructionsForModel(model ?? '');
}
